import React, { forwardRef } from 'react';
import styled from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import BoxShadows from '@dynatrace/strato-design-tokens/box-shadows';
import Colors from '@dynatrace/strato-design-tokens/colors';

import { FocusScope } from '../../core/components/focus-scope/FocusScope.js';
import { OverlayContainer } from '../../core/components/OverlayContainer.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { useOverlayStacking } from '../../core/hooks/useOverlayStacking.js';
import { OverlayStackingProvider } from '../../core/providers/OverlayStackingProvider.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import type { OverlayProps } from '../hooks/useOverlayWithTrigger.js';

export interface OverlayComponentProps
  extends AriaLabelingProps,
    WithChildren,
    DataTestId,
    StylingProps {
  /** Whether the overlay is open. */
  isOpen: OverlayProps['overlayState']['isOpen'];
  /**
   * Properties for connecting the overlay to the overlay trigger.
   * Includes styles and accessibility attributes.
   */
  overlayProps?: OverlayProps['overlayProps'];
}

// #region StyledComponents
const StyledOverlay = /* @__PURE__ */ styled('div')({
  background: Colors.Background.Surface.Default,
  borderRadius: Borders.Radius.Surface.Subdued,
  boxShadow: BoxShadows.Surface.Floating.Rest,
  wordBreak: 'normal',
  overflowWrap: 'anywhere',
  width: 'max-content',
  overflowY: 'auto',
});
// #endregion

/**
 * The `Overlay` component allows you to show additional content when the user
 * clicks on a particular element in the UI. The `Overlay` is placed
 * at the border of its trigger element. To define a UI element as
 * a trigger, use the `useOverlayWithTrigger` hook. The Overlay only
 * exists in a controlled manner, so the `isOpen` prop must be
 * updated by the developer.
 */
export const Overlay = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  OverlayComponentProps
>((props, forwardedRef) => {
  const {
    isOpen,
    children,
    overlayProps,
    className: customClassName,
    style: customStyles,
    'data-testid': dataTestId,
    ...remainingProps
  } = props;
  const ariaProps = _useAriaLabelingProps(remainingProps);

  const overlayContainerProps = useOverlayStacking(undefined, 'dropdown');

  if (!isOpen) {
    return null;
  }

  return (
    <OverlayContainer data-testid={dataTestId} {...overlayContainerProps}>
      <FocusScope contain={overlayProps?.trapFocus} autoFocus>
        <StyledOverlay
          ref={forwardedRef}
          className={customClassName}
          style={customStyles}
          {..._mergeProps(overlayProps, ariaProps)}
        >
          <OverlayStackingProvider>{children}</OverlayStackingProvider>
        </StyledOverlay>
      </FocusScope>
    </OverlayContainer>
  );
});

(Overlay as typeof Overlay & { displayName: string }).displayName = 'Overlay';
